import{_ as p,a0 as l,w as o,s as r,ao as d,I as t,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"Sosreport：收集系统日志和诊断信息的工具 | LCTT x X-CMD","titleTemplate":false,"description":"Sosreport：收集系统日志和诊断信息的工具 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Sosreport：收集系统日志和诊断信息的工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Sosreport：收集系统日志和诊断信息的工具 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180628 Sosreport - A Tool To Collect System Logs And Diagnostic Information","title":"Sosreport：收集系统日志和诊断信息的工具","tag":"201807","desc":""},"relativePath":"201807/20180628 Sosreport - A Tool To Collect System Logs And Diagnostic Information.md","filePath":"[post].md"}'),c={name:"201807/20180628 Sosreport - A Tool To Collect System Logs And Diagnostic Information.md"};function h(g,s,u,k,b,f){const n=l("Link");return o(),r("div",null,[s[15]||(s[15]=d(`<h1 id="sosreport-收集系统日志和诊断信息的工具" tabindex="-1">Sosreport：收集系统日志和诊断信息的工具 <a class="header-anchor" href="#sosreport-收集系统日志和诊断信息的工具" aria-label="Permalink to “Sosreport：收集系统日志和诊断信息的工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/06/sos-720x340.png" alt=""></p><p>如果你是 RHEL 管理员，你可能肯定听说过 <strong>Sosreport</strong> ：一个可扩展、可移植的支持数据收集工具。它是一个从类 Unix 操作系统中收集系统配置详细信息和诊断信息的工具。当用户提出支持服务单时，他/她必须运行此工具并将由 Sosreport 工具生成的结果报告发送给 Red Hat 支持人员。然后，执行人员将根据报告进行初步分析，并尝试找出系统中的问题。不仅在 RHEL 系统上，你可以在任何类 Unix 操作系统上使用它来收集系统日志和其他调试信息。</p><h3 id="安装-sosreport" tabindex="-1">安装 Sosreport <a class="header-anchor" href="#安装-sosreport" aria-label="Permalink to “安装 Sosreport”">​</a></h3><p>Sosreport 在 Red Hat 官方系统仓库中，因此你可以使用 Yum 或 DNF 包管理器安装它，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install sos</span></span></code></pre></div><p>要么，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install sos</span></span></code></pre></div><p>在 Debian、Ubuntu 和 Linux Mint 上运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install sosreport</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>安装后，运行以下命令以收集系统配置详细信息和其他诊断信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sosreport</span></span></code></pre></div><p>系统将要求你输入系统的一些详细信息，例如系统名称、案例 ID 等。相应地输入详细信息，然后按回车键生成报告。如果你不想更改任何内容并使用默认值，只需按回车键即可。</p><p>我的 CentOS 7 服务器的示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sosreport (version 3.5)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>This command will collect diagnostic and configuration information from</span></span>
<span class="line"><span>this CentOS Linux system and installed applications.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>An archive containing the collected information will be generated in</span></span>
<span class="line"><span>/var/tmp/sos.DiJXi7 and may be provided to a CentOS support</span></span>
<span class="line"><span>representative.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Any information provided to CentOS will be treated in accordance with</span></span>
<span class="line"><span>the published support policies at:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>https://wiki.centos.org/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The generated archive may contain data considered sensitive and its</span></span>
<span class="line"><span>content should be reviewed by the originating organization before being</span></span>
<span class="line"><span>passed to any third party.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No changes will be made to system configuration.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Press ENTER to continue, or CTRL-C to quit.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please enter your first initial and last name [server.ostechnix.local]:</span></span>
<span class="line"><span>Please enter the case id that you are generating this report for []:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Setting up archive ...</span></span>
<span class="line"><span>Setting up plugins ...</span></span>
<span class="line"><span>Running plugins. Please wait ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Running 73/73: yum...</span></span>
<span class="line"><span>Creating compressed archive...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Your sosreport has been generated and saved in:</span></span>
<span class="line"><span>/var/tmp/sosreport-server.ostechnix.local-20180628171844.tar.xz</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The checksum is: 8f08f99a1702184ec13a497eff5ce334</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please send this file to your support representative.</span></span></code></pre></div><p>如果你不希望系统提示你输入此类详细信息，请如下使用批处理模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sosreport --batch</span></span></code></pre></div><p>正如你在上面的输出中所看到的，生成了一个归档报告并保存在 <code>/var/tmp/sos.DiJXi7</code> 中。在 RHEL 6/CentOS 6 中，报告将在 <code>/tmp</code> 中生成。你现在可以将此报告发送给你的支持人员，以便他可以进行初步分析并找出问题所在。</p><p>你可能会担心或想知道报告中的内容。如果是这样，你可以通过运行以下命令来查看它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo tar -tf /var/tmp/sosreport-server.ostechnix.local-20180628171844.tar.xz</span></span></code></pre></div><p>要么，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vim /var/tmp/sosreport-server.ostechnix.local-20180628171844.tar.xz</span></span></code></pre></div><p>请注意，上述命令不会解压存档，而只显示存档中的文件和文件夹列表。如果要查看存档中文件的实际内容，请首先使用以下命令解压存档：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo tar -xf /var/tmp/sosreport-server.ostechnix.local-20180628171844.tar.xz</span></span></code></pre></div><p>存档的所有内容都将解压当前工作目录中 <code>ssosreport-server.ostechnix.local-20180628171844/</code> 目录中。进入目录并使用 <code>cat</code> 命令或任何其他文本浏览器查看文件内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd sosreport-server.ostechnix.local-20180628171844/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat uptime</span></span>
<span class="line"><span>17:19:02 up 1:03, 2 users, load average: 0.50, 0.17, 0.10</span></span></code></pre></div><p>有关 Sosreport 的更多详细信息，请参阅手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man sosreport</span></span></code></pre></div><p>就是这些了。希望这些有用。还有更多好东西。敬请关注！</p><p>干杯！</p><hr>`,32)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.ostechnix.com/sosreport-a-tool-to-collect-system-logs-and-diagnostic-information/"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.ostechnix.com/sosreport-a-tool-to-collect-system-logs-and-diagnostic-information/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:i(()=>[...s[2]||(s[2]=[a("SK",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=p(c,[["render",h]]);export{v as __pageData,C as default};
